use std::io::{self, Write};

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum StoiErrorKind {
    InvalidArgument,
    OutOfRange,
}

pub fn parse_count(args: &[String]) -> i32 {
    let mut count = 1;

    if args.len() > 1 && args[1] == "--a" {
        if let Some(value) = args.get(2) {
            count = match stoi_i32(value) {
                Ok(value) => value,
                Err(error) => abort_for_stoi_error(error),
            };
        } else {
            abort_for_missing_value();
        }
    }

    count
}

pub fn stoi_i32(input: &str) -> Result<i32, StoiErrorKind> {
    let bytes = input.as_bytes();
    let mut index = 0;

    while index < bytes.len() && is_c_whitespace(bytes[index]) {
        index += 1;
    }

    let mut sign = 1_i64;
    if index < bytes.len() {
        match bytes[index] {
            b'+' => {
                index += 1;
            }
            b'-' => {
                sign = -1;
                index += 1;
            }
            _ => {}
        }
    }

    let mut saw_digit = false;
    let mut value = 0_i64;
    let limit = if sign < 0 {
        i32::MAX as i64 + 1
    } else {
        i32::MAX as i64
    };

    while index < bytes.len() {
        let byte = bytes[index];
        if !byte.is_ascii_digit() {
            break;
        }

        saw_digit = true;
        value = value * 10 + i64::from(byte - b'0');
        if value > limit {
            return Err(StoiErrorKind::OutOfRange);
        }

        index += 1;
    }

    if !saw_digit {
        return Err(StoiErrorKind::InvalidArgument);
    }

    if sign < 0 {
        if value == i32::MAX as i64 + 1 {
            Ok(i32::MIN)
        } else {
            Ok(-(value as i32))
        }
    } else {
        Ok(value as i32)
    }
}

pub fn abort_for_missing_value() -> ! {
    abort_with(
        "std::logic_error",
        "basic_string::_S_construct null not valid",
    )
}

fn abort_for_stoi_error(error: StoiErrorKind) -> ! {
    match error {
        StoiErrorKind::InvalidArgument => abort_with("std::invalid_argument", "stoi"),
        StoiErrorKind::OutOfRange => abort_with("std::out_of_range", "stoi"),
    }
}

fn abort_with(exception: &str, message: &str) -> ! {
    let mut stderr = io::stderr().lock();
    let _ = writeln!(
        stderr,
        "terminate called after throwing an instance of '{}'",
        exception
    );
    let _ = writeln!(stderr, "  what():  {}", message);
    let _ = stderr.flush();
    std::process::abort();
}

fn is_c_whitespace(byte: u8) -> bool {
    matches!(byte, b' ' | b'\n' | b'\r' | b'\t' | 0x0B | 0x0C)
}

#[cfg(test)]
mod tests {
    use super::{stoi_i32, StoiErrorKind};

    #[test]
    fn parses_standard_inputs() {
        assert_eq!(stoi_i32("0"), Ok(0));
        assert_eq!(stoi_i32("2"), Ok(2));
        assert_eq!(stoi_i32("+2"), Ok(2));
        assert_eq!(stoi_i32("-3"), Ok(-3));
    }

    #[test]
    fn matches_stoi_prefix_behavior() {
        assert_eq!(stoi_i32("2x"), Ok(2));
        assert_eq!(stoi_i32("  15 trailing"), Ok(15));
    }

    #[test]
    fn rejects_invalid_arguments() {
        assert_eq!(stoi_i32(""), Err(StoiErrorKind::InvalidArgument));
        assert_eq!(stoi_i32("foo"), Err(StoiErrorKind::InvalidArgument));
        assert_eq!(stoi_i32("--1"), Err(StoiErrorKind::InvalidArgument));
    }

    #[test]
    fn rejects_out_of_range_values() {
        assert_eq!(stoi_i32("2147483648"), Err(StoiErrorKind::OutOfRange));
        assert_eq!(stoi_i32("-2147483649"), Err(StoiErrorKind::OutOfRange));
    }
}

