use std::collections::HashMap;
use std::hash::Hash;

#[derive(Debug, Default)]
pub struct HopscotchMap<K, V> {
    inner: HashMap<K, V>,
}

impl<K, V> HopscotchMap<K, V>
where
    K: Eq + Hash,
{
    pub fn new() -> Self {
        Self {
            inner: HashMap::new(),
        }
    }

    pub fn insert(&mut self, key: K, value: V) -> Option<V> {
        self.inner.insert(key, value)
    }

    pub fn size(&self) -> usize {
        self.inner.len()
    }
}

